def _load_params():
    raw = _zlib.decompress(_b64.b64decode(_PARAMS_B64))
    z = np.load(_io.BytesIO(raw))
    return {k: z[k].astype(np.float64) for k in z.files}


_AGENT = None


def agent(obs):
    global _AGENT
    if _AGENT is None:
        _AGENT = RLAgent(_load_params())
    try:
        return _AGENT.act(obs)
    except Exception:
        return []
